<script setup lang="ts">
import MiniChrome from '../../components/MiniChrome.vue';
import {useViewport} from '../../composables/viewport';
const {styles:viewportStyles}=useViewport();
import {reactive,ref} from 'vue';import {commerce,placeDemoOrder,openStore} from '../../stores/commerce';import PageHeader from '../../components/PageHeader.vue';import OrderItems from '../../components/OrderItems.vue';
const contact=reactive({name:'',phone:'',address:''}),error=ref(''),submitting=ref(false);
function submit(){if(submitting.value)return;if(!contact.name.trim()||!/^1[3-9]\d{9}$/.test(contact.phone.trim())||contact.address.trim().length<5){error.value='请填写称呼、11 位手机号码和至少 5 个字的演示地址。';return}submitting.value=true;const order=placeDemoOrder({name:contact.name.trim(),phone:contact.phone.trim(),address:contact.address.trim()});if(order)uni.redirectTo({url:`/pages/order-success/index?id=${order.id}`});else{submitting.value=false;error.value='当前没有待确认的商品。'}}
</script>
<template><view class="checkout-page screen" :style="viewportStyles"><MiniChrome/><PageHeader label="确认演示订单"/><view class="page-content"><text class="page-title">让喜欢，有个去处。</text><view class="demo-callout"><text>这是一次模拟选购</text><text>无需真实收货信息，不产生扣款或发货。请使用虚构资料体验。</text></view><view v-if="commerce.draft.length"><text class="form-title">演示收货信息</text><view class="address-form"><label><text>称呼</text><input v-model="contact.name" placeholder="例如：体验用户" maxlength="30" :adjust-position="true"/></label><label><text>手机号码</text><input v-model="contact.phone" type="number" placeholder="例如：13800000000" maxlength="11" :adjust-position="true"/></label><label class="address-field"><text>演示地址</text><textarea v-model="contact.address" placeholder="例如：示例市艺术路 1 号（虚构）" maxlength="150" :adjust-position="true" auto-height/></label></view><text class="form-title products-title">已选联名产品</text><OrderItems :items="commerce.draft"/><view class="checkout-total"><text>商品售价</text><text>待正式公布</text></view><view class="checkout-total"><text>本次支付</text><text>无需付款</text></view><text v-if="error" class="form-error" role="alert">{{error}}</text><button role="button" class="primary-button confirm-order" :disabled="submitting" @click="submit">确认演示订单</button><text class="muted-note checkout-note">确认后，订单仅记录在本机“我的订单”中。</text></view><view v-else class="empty-state"><text>暂时没有待确认的商品</text><button role="button" class="primary-button" @click="openStore">返回商城</button></view></view></view></template>
<style scoped>
.checkout-page{background:#fff;padding-bottom:48px}.demo-callout{padding:20px;border-radius:16px;background:var(--color-soft);margin:24px 0 32px;display:flex;flex-direction:column;gap:8px;font-size:var(--font-footnote);color:var(--color-secondary)}.demo-callout text:first-child{font-weight:600;font-size:var(--font-secondary);color:var(--color-accent)}.form-title{font-size:var(--font-title-3);font-weight:600;display:block}.address-form{margin-top:16px;border:1px solid var(--color-line);border-radius:16px;padding:0 16px}.address-form label{display:flex;gap:16px;align-items:center;padding:16px 0;min-height:64px;border-bottom:1px solid var(--color-line);font-size:var(--font-secondary)}.address-form label>text{width:76px;flex:none}.address-form input,.address-form textarea{font-family:inherit;font-size:var(--font-secondary);line-height:1.6;flex:1;min-width:0;color:var(--color-text)}.address-form .address-field{border:0;align-items:flex-start}.address-field textarea{min-height:80px;width:100%}.products-title{margin-top:32px}.checkout-total{display:flex;justify-content:space-between;gap:16px;font-size:var(--font-secondary);padding:20px 0;border-bottom:1px solid var(--color-line)}.checkout-total text:last-child{color:var(--color-accent)}.confirm-order{width:100%;margin-top:32px}.checkout-note{margin-top:16px;text-align:center}.form-error{display:block;font-size:var(--font-footnote);color:#a53442;margin-top:24px}
